<script setup lang="ts">
import {computed,ref} from 'vue';
import {Plus,Pencil,Trash2,Check} from 'lucide-vue-next';
import ItemForm from './ItemForm.vue';
import {emptyNote,itemDone,toggleItem,scheduleLabel} from './content.ts';
import type {DesktopWidget,WidgetContent,TodoItem,ReminderItem} from './model.ts';
const props=defineProps<{widget:DesktopWidget;save:(content:WidgetContent)=>Promise<void>}>();
const todo=computed(()=>props.widget.kind==='notes'),editing=ref(false),chosen=ref<TodoItem|ReminderItem>(),busy=ref(false),error=ref('');
const items=computed(():Array<TodoItem|ReminderItem>=>todo.value?props.widget.note?.items??[]:[...(props.widget.living?.reminders??[])].sort((a,b)=>a.at.localeCompare(b.at)));
function label(item:TodoItem|ReminderItem){return 'text'in item?item.text:item.title;}
function when(item:TodoItem|ReminderItem){return 'text'in item?scheduleLabel(item.date||'',item.time||'',item.repeat):scheduleLabel(item.at.slice(0,10),item.at.slice(11),item.repeat);}
function open(item?:TodoItem|ReminderItem){chosen.value=item;editing.value=true;error.value='';}
async function persist(list:Array<TodoItem|ReminderItem>){busy.value=true;error.value='';try{if(todo.value)await props.save({note:{...(props.widget.note??emptyNote()),items:list as TodoItem[]}});else await props.save({living:{...(props.widget.living??{count:0,symbol:'1.000001',reminders:[]}),reminders:list as ReminderItem[]}});return true;}catch(e){error.value=String(e);return false;}finally{busy.value=false;}}
async function commit(item:TodoItem|ReminderItem){const list=items.value.some(i=>i.id===item.id)?items.value.map(i=>i.id===item.id?item:i):[...items.value,item];if(await persist(list))editing.value=false;}
async function toggle(item:TodoItem|ReminderItem){await persist(items.value.map(i=>i.id===item.id?toggleItem(i):i));}
</script>
<template><section class="item-manager"><header><strong>{{ todo?'待办管理':'全部日程' }} <small>{{ items.length }} / 12</small></strong><button :disabled="busy||items.length>=12" @click="open()"><Plus :size="15"/>新增</button></header><p class="manager-help">{{ todo?'编辑事项内容、日期及提醒。':'包含过去与未来日程；重复日程完成仅影响当天。' }}</p><ItemForm v-if="editing" :key="chosen?.id||'new'" :mode="todo?'todo':'agenda'" :item="chosen" :busy="busy" @save="commit" @cancel="editing=false"/><div v-else class="manager-list"><article v-for="item in items" :key="item.id"><button class="manager-done" :class="{on:itemDone(item)}" :aria-label="`${itemDone(item)?'恢复':'完成'}${label(item)}`" :disabled="busy" @click="toggle(item)"><Check v-if="itemDone(item)" :size="15"/></button><div><strong :class="{done:itemDone(item)}">{{ label(item) }}</strong><small>{{ when(item) }}{{ item.notify??!todo?' · 开启提醒':'' }}</small><small v-if="'location'in item&&item.location">{{ item.location }}</small></div><button :disabled="busy" aria-label="编辑事项" @click="open(item)"><Pencil :size="15"/></button><button :disabled="busy" aria-label="删除事项" @click="persist(items.filter(i=>i.id!==item.id))"><Trash2 :size="15"/></button></article><p v-if="!items.length" class="manager-help">还没有事项，点击新增。</p></div><p v-if="error" role="alert">{{ error }}</p></section></template>
<style scoped>.item-manager{font-size:13px}.item-manager header{display:flex;justify-content:space-between;align-items:center}.item-manager header small{font-weight:400;color:var(--ui-text-tertiary)}.item-manager button{display:flex;gap:5px;align-items:center;justify-content:center;background:none;border:0;color:inherit;font:inherit;padding:5px;cursor:pointer}.manager-help{font-size:12px;color:var(--ui-text-tertiary);line-height:1.6}.manager-list{display:grid;gap:5px}.manager-list article{display:flex;align-items:center;gap:9px;padding:9px 0;border-bottom:1px solid var(--ui-border)}.manager-list article>div{flex:1;min-width:0;display:grid;gap:4px;overflow-wrap:anywhere}.manager-list strong{font-weight:500}.manager-list small{font-size:11px;color:var(--ui-text-tertiary)}.manager-list .done{text-decoration:line-through;opacity:.5}.manager-done{border:1px solid #b7a48f!important;border-radius:50%;width:23px;height:23px;flex:none}.manager-done.on{background:#b79b7e;color:#fff}.item-manager>p[role=alert]{color:#bd6758}</style>
